module ApplicationHelper
  def option_letter(index)
    # Like spreadsheet columns: A–Z, then AA, AB, and so on.
    letter = ""
    loop do
      index, remainder = index.divmod(26)
      letter.prepend(("A".ord + remainder).chr)
      return letter if index.zero?
      index -= 1
    end
  end
end
EOF
