#!/usr/bin/env ruby

require "bundler/setup"
require "capybara/cuprite"
require "minitest/autorun"
require "capybara/minitest"
require "net/http"
require "securerandom"

# Run against a locally started server, with the same credentials as bin/serve.
Capybara.configure do |config|
  config.run_server = false
  config.app_host = ENV.fetch("QUIZZY_TEST_URL", "http://127.0.0.1:3000")
  config.default_max_wait_time = 5
  config.enable_aria_label = true
end
Capybara.register_driver(:quizzy_chromium) do |app|
  Capybara::Cuprite::Driver.new(app, browser_path: ENV.fetch("CHROME_PATH", "/usr/bin/chromium"),
    browser_options: { "no-sandbox" => nil, "disable-dev-shm-usage" => nil }, window_size: [390, 844])
end

class QuizzySmokeTest < Minitest::Test
  include Capybara::Minitest::Assertions

  def setup
    @username = ENV.fetch("QUIZZY_MODERATOR_USERNAME")
    @password = ENV.fetch("QUIZZY_MODERATOR_PASSWORD")
  end

  def teardown
    @page&.driver&.quit
  end

  def test_startup_and_authentication
    assert_equal "200", request("/up").code
    assert_equal "401", request("/moderate").code
    assert_equal "401", request("/moderate/quizzes/new", @username, "not-#{@password}").code
    assert_equal "200", request("/moderate", @username, @password).code
  end

  def test_preparing_and_previewing_a_quiz
    title = "Smoke test #{SecureRandom.hex(4)}"
    @page = Capybara::Session.new(:quizzy_chromium)
    @page.driver.browser.network.authorize(user: @username, password: @password) { |req| req.continue }
    @page.visit("/moderate")
    @page.click_link("New quiz")
    @page.fill_in("Title", with: title)
    @page.click_button("Save quiz")
    assert_selector @page, "h1", exact_text: title

    @page.click_link("Preview")
    assert_text @page, "No active questions"
    @page.click_link("← Back to quiz")

    @page.click_link("Add question")
    assert_selector @page, "[data-option-rows] .option-row", count: 4
    assert_selector @page, :checkbox, "Active", checked: true
    @page.fill_in("Question", with: "Which are primary colors of light?")
    @page.fill_in("Option 1", with: "Blue")
    @page.check("Option 2 is correct") # Marking a blank option must not count.
    @page.click_button("Save question")
    assert_text @page, "Add at least two options"
    assert_text @page, "Mark at least one option as correct"
    assert_field @page, "Option 1", with: "Blue"
    assert_field @page, "Question", with: "Which are primary colors of light?"
    assert_selector @page, :checkbox, "Option 2 is correct", checked: true
    @page.fill_in("Option 3", with: "Green")
    @page.click_button("Save question")
    assert_text @page, "Mark at least one option as correct"
    @page.check("Option 1 is correct")
    @page.check("Option 3 is correct")
    @page.click_button("Add option")
    @page.fill_in("Option 5", with: "Yellow")
    @page.click_button("Save question")
    assert_selector @page, ".question-item__options li", count: 3
    assert_selector @page, ".question-item__options .is-correct", count: 2

    add_question("Which planet is largest?", "Jupiter", "Earth")
    add_question("What is 2 + 2?", "4", "3")
    question("What is 2 + 2?").click_button("Move up")
    assert_equal ["Which are primary colors of light?", "What is 2 + 2?", "Which planet is largest?"], question_order
    question("Which are primary colors of light?").click_button("Move down")
    assert_equal ["What is 2 + 2?", "Which are primary colors of light?", "Which planet is largest?"], question_order
    question("Which planet is largest?").uncheck("Active")
    assert_selector @page, "li.question-item--inactive", text: "Which planet is largest?"

    question("What is 2 + 2?").click_link("Edit")
    @page.fill_in("Question", with: "What is two plus two?")
    @page.fill_in("Option 2", with: "5")
    @page.click_button("Save question")
    assert_selector @page, "li.question-item", text: "What is two plus two?"

    @page.click_link("Preview")
    assert_text @page, "Question 1 of 2"
    assert_text @page, "What is two plus two?"
    @page.click_button("4", exact: true)
    assert_text @page, "Correct!"
    @page.click_button("Next question")
    assert_text @page, "Question 2 of 2"
    @page.click_button("Yellow", exact: true)
    assert_text @page, "Wrong!"
    assert_selector @page, ".play-option.is-correct", count: 2
    @page.click_button("See score")
    assert_text @page, "Score: 1/2"
    @page.click_button("Start over")
    assert_text @page, "Question 1 of 2"
    refute_text @page, "Score: 1/2"
    @page.click_link("← Back to quiz")

    @page.dismiss_confirm { question("Which planet is largest?").click_button("Delete") }
    assert_selector @page, "li.question-item", text: "Which planet is largest?"
    @page.accept_confirm { question("Which planet is largest?").click_button("Delete") }
    assert_no_selector @page, "li.question-item", text: "Which planet is largest?"

    @page.click_link("Settings")
    @page.fill_in("Title", with: "#{title} renamed")
    @page.click_button("Save quiz")
    assert_selector @page, "h1", exact_text: "#{title} renamed"
    @page.click_link("Settings")
    @page.dismiss_confirm { @page.click_button("Delete quiz") }
    assert_selector @page, "h1", exact_text: "Settings"
    @page.accept_confirm { @page.click_button("Delete quiz") }
    assert_selector @page, "h1", exact_text: "Quizzes"
    assert_no_selector @page, ".quiz-list li", text: title
  end

  private

  def request(path, user = nil, password = nil)
    uri = URI.join(Capybara.app_host, path)
    request = Net::HTTP::Get.new(uri)
    request["Host"] = "quizzy.conference.test:#{uri.port}"
    request.basic_auth(user, password) if user
    Net::HTTP.start(uri.host, uri.port, nil) { |http| http.request(request) }
  end

  def add_question(body, right, wrong)
    @page.click_link("Add question")
    @page.fill_in("Question", with: body)
    @page.fill_in("Option 1", with: right)
    @page.check("Option 1 is correct")
    @page.fill_in("Option 2", with: wrong)
    @page.click_button("Save question")
    assert_selector @page, "li.question-item", text: body
  end

  def question(body)
    @page.find("li.question-item", text: body)
  end

  def question_order
    @page.all(".question-item__body").map(&:text)
  end
end
EOF
